const payload = $input.first().json;
const posts = Array.isArray(payload.posts) ? payload.posts : [];
if (!Array.isArray(posts)) {
  throw new Error('Threads miner must return posts as a JSON array.');
}

return posts
  .filter(p => p && p.id && p.url)
  .map(p => ({ json: p }));

function cleanText(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

const env = (typeof process !== 'undefined' && process.env) ? process.env : {};
const enabled = ['1', 'true', 'yes'].includes(String(env.THREADS_CLASSIFIER_ENABLED || 'true').trim().toLowerCase());
const model = String(env.THREADS_CLASSIFIER_MODEL || 'gemini-2.5-flash-lite').trim();

return $input.all().map(item => {
  const preview = cleanText(item.json.text_preview || '');
  const fitScore = Number(item.json.content_fit_score || 0);
  const fitTags = Array.isArray(item.json.content_fit_tags) ? item.json.content_fit_tags : [];
  const engagementScore = Number(item.json.engagement_score || 0);
  const engagementMetrics = Array.isArray(item.json.engagement_metrics) ? item.json.engagement_metrics : [];
  const strongestMetric = Number(item.json.engagement_strongest_metric || 0);
  const metricCount = Number(item.json.engagement_metric_count || 0);

  item.json._classifier = {
    enabled,
    model,
    preview,
    fitScore,
    fitTags,
    engagementScore,
    engagementMetrics,
    strongestMetric,
    metricCount,
    prompt: [
      'Ban la bo loc noi dung cho kenh video ngan tieng Viet.',
      'Hay danh gia preview cua mot bai Threads xem co nen dua vao pipeline lam video binh luan hay ke chuyen dang hot khong.',
      'CHI GIU lai cac bai co chat lieu ro rang cho mot trong ba huong: discussion (gay tranh luan, hoi y kien, co goc nhin, co the binh luan them), story_hot (dang ke mot cau chuyen, drama, tinh huong hot, co dien bien de tom tat), hoac topic_hot (ban ve chu de xa hoi dang nong nhu thoi tiet, gia nha, kinh te, chinh tri, giao thong, hoc phi, luong, van de cong chung).',
      'UU TIEN bai co dau hieu tuong tac that su, dac biet khi metric_count >= 2 hoac strongest_metric cao. NEU preview qua chung chung, qua doi thuong, hoac khong mo ra goc de ban luan/chia se thi phai reject.',
      'LOAI bo cac bai chi la anh/video doi thuong, status vo thuong vo phat, cau cam than ngan, caption linh tinh, ban hang, self-promo, repost vo nghia, hoac post khong du chat lieu de lam video 30-60 giay.',
      'Duoc phep dung fit score va engagement lam ngu canh phu, nhung quyet dinh chinh phai dua tren noi dung text preview.',
      'Tra ve DUY NHAT mot JSON hop le theo schema: {"decision":"keep|reject","angle":"discussion|story_hot|topic_hot|reject","confidence":0.0,"reason":"..."}.',
      'reason phai ngan gon, neu reject thi noi ro ly do chinh.',
    ].join(' '),
  };

  return item;
});

function cleanText(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function parseJsonCandidate(text) {
  const cleaned = cleanText(text);
  if (!cleaned) return null;

  const fencedMatch = cleaned.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const jsonSource = fencedMatch ? fencedMatch[1] : cleaned;
  const braceMatch = jsonSource.match(/\{[\s\S]*\}/);
  const candidate = braceMatch ? braceMatch[0] : jsonSource;

  try {
    const parsed = JSON.parse(candidate);
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch (error) {
    return null;
  }
}

function extractTextDeep(value, bucket = []) {
  if (typeof value === 'string') {
    const cleaned = cleanText(value);
    if (cleaned) bucket.push(cleaned);
    return bucket;
  }

  if (!value || typeof value !== 'object') return bucket;
  if (Array.isArray(value)) {
    value.forEach(entry => extractTextDeep(entry, bucket));
    return bucket;
  }

  Object.values(value).forEach(entry => {
    if (typeof entry === 'string') {
      const cleaned = cleanText(entry);
      if (cleaned) bucket.push(cleaned);
    } else if (entry && typeof entry === 'object') {
      extractTextDeep(entry, bucket);
    }
  });
  return bucket;
}

function extractClassifierDecision(data) {
  if (!data || typeof data !== 'object') return null;

  const direct = [data.output, data.text, data.content, data.message, data.response].filter(Boolean);
  for (const candidate of direct) {
    const parsed = parseJsonCandidate(candidate);
    if (parsed) return parsed;
  }

  for (const candidate of extractTextDeep(data, [])) {
    const parsed = parseJsonCandidate(candidate);
    if (parsed) return parsed;
  }

  return null;
}

const kept = [];

for (const item of $input.all()) {
  const classifier = item.json._classifier || {};
  const preview = cleanText(classifier.preview || item.json.text_preview || '');
  const fitScore = Number(classifier.fitScore || item.json.content_fit_score || 0);
  const fitTags = Array.isArray(classifier.fitTags || item.json.content_fit_tags) ? (classifier.fitTags || item.json.content_fit_tags) : [];
  const strongestMetric = Number(classifier.strongestMetric || item.json.engagement_strongest_metric || 0);
  const metricCount = Number(classifier.metricCount || item.json.engagement_metric_count || 0);
  const classifierEnabled = classifier.enabled !== false;
  const fallbackKeep = fitScore >= 4 && preview.length >= 110 && metricCount >= 2 && (fitTags.includes('discussion') || fitTags.includes('story') || fitTags.includes('topic-hot'));
  const parsed = classifierEnabled ? extractClassifierDecision(item.json) : null;

  let decision = fallbackKeep ? 'keep' : 'reject';
  let angle = fitTags.includes('discussion') ? 'discussion' : (fitTags.includes('story') ? 'story_hot' : (fitTags.includes('topic-hot') ? 'topic_hot' : 'reject'));
  let confidence = fallbackKeep ? 0.6 : 0.35;
  let reason = fallbackKeep
    ? `heuristic keep fit=${fitScore} metricCount=${metricCount} strongest=${strongestMetric} tags=${fitTags.join(',') || 'none'}`
    : `heuristic reject fit=${fitScore} metricCount=${metricCount} strongest=${strongestMetric} preview_too_weak`;

  if (!classifierEnabled) {
    reason = `ai disabled; ${reason}`;
  } else if (parsed) {
    const parsedDecision = cleanText(parsed.decision || '').toLowerCase();
    const parsedAngle = cleanText(parsed.angle || '').toLowerCase();
    const parsedReason = cleanText(parsed.reason || '');
    const parsedConfidence = Number(parsed.confidence || 0);
    if ((parsedDecision === 'keep' || parsedDecision === 'reject') && ['discussion', 'story_hot', 'topic_hot', 'reject'].includes(parsedAngle || 'reject')) {
      decision = parsedDecision;
      angle = parsedAngle || (parsedDecision === 'keep' ? 'discussion' : 'reject');
      confidence = Number.isFinite(parsedConfidence) ? parsedConfidence : confidence;
      reason = parsedReason || reason;
    }
  } else {
    reason = `ai fallback; ${reason}`;
  }

  item.json._classifier_decision = decision;
  item.json._classifier_angle = angle;
  item.json._classifier_confidence = Math.max(0, Math.min(1, confidence || 0));
  item.json._classifier_reason = reason;

  if (decision === 'keep' && ['discussion', 'story_hot', 'topic_hot'].includes(angle)) {
    kept.push(item);
  }
}

return kept;
